// Validar que venga el archivo
const file = $input.first().binary.file;

if (!file) {
    return [{ error: "No se proporcionó archivo válido" }];
}

// Validar tipo de archivo
const allowedTypes = ['pdf', 'docx', 'txt', 'doc'];
const fileName = file.fileName || '';
const fileExtension = fileName.split('.').pop().toLowerCase();

if (!allowedTypes.includes(fileExtension)) {
    return [{ error: "Tipo de archivo no permitido. Use PDF, DOCX o TXT" }];
}

// Validar tamaño (max 10MB)
if (file.data.length > 10 * 1024 * 1024) {
    return [{ error: "Archivo demasiado grande. Máximo 10MB" }];
}

return [{
    json: {
        fileName: fileName,
        fileExtension: fileExtension,
        fileSize: file.data.length,
        fileBuffer: file.data
    },
    binary: {
        file: file
    }
}];

const { fileName, fileExtension, fileBuffer } = $input.first().json;
let extractedText = '';

async function processFile() {
    try {
        if (fileExtension === 'pdf') {
            // Para PDF necesitarías un servicio externo o función
            extractedText = "Texto extraído de PDF: [Contenido procesado]";

        } else if (fileExtension === 'docx') {
            // Para DOCX necesitarías un servicio externo
            extractedText = "Texto extraído de DOCX: [Contenido procesado]";

        } else if (fileExtension === 'txt') {
            // TXT es simple
            extractedText = fileBuffer.toString('utf8');
        }

        return {
            extractedText,
            fileName,
            fileExtension,
            success: true
        };

    } catch (error) {
        return {
            error: `Error procesando archivo: ${error.message}`,
            success: false
        };
    }
}

const result = await processFile();
return [{ json: result }];

const input = $input.first().json;

if (!input.success) {
    return [{ json: { error: input.error } }];
}

const { extractedText, fileName, fileExtension } = input;

// Dividir texto en chunks
const chunkSize = 1000;
const chunks = [];

for (let i = 0; i < extractedText.length; i += chunkSize) {
    const chunk = extractedText.slice(i, i + chunkSize);
    const lines = chunk.split('\n');
    let sectionTitle = 'Sin título';

    // Buscar título
    for (const line of lines.slice(0, 5)) {
        if (line.trim().length > 10 && line.trim().length < 100) {
            sectionTitle = line.trim().substring(0, 100);
            break;
        }
    }

    chunks.push({
        chunkNumber: chunks.length + 1,
        content: chunk,
        sectionTitle: sectionTitle,
        wordCount: chunk.split(/\s+/).length
    });
}

return [{
    json: {
        fileName,
        fileExtension,
        chunks,
        totalChunks: chunks.length,
        totalTextLength: extractedText.length,
        storagePath: `gym-documents/${fileName}`
    }
}];

const fileId = $input.first().json[0].id;
const chunks = $json.chunks;

const chunksWithFileId = chunks.map(chunk => ({
    file_id: fileId,
    chunk_number: chunk.chunkNumber,
    content: chunk.content.substring(0, 10000), // Limitar tamaño
    section_title: chunk.sectionTitle,
    word_count: chunk.wordCount
}));

return chunksWithFileId.map(chunk => ({ json: chunk }));

const fileData = $input.first().json;

return [{
    json: {
        success: true,
        message: "Archivo procesado exitosamente",
        fileId: fileData.id,
        fileName: fileData.filename,
        totalChunks: fileData.totalChunks,
        processedAt: new Date().toISOString()
    }
}];
